export type Align = 'left' | 'center' | 'right' | 'justify' | 'distribute' | 'distribute_space';

// ─── 이미지 배치 ────────────────────────────────────────────
export type ImgWrap = 'inline' | 'square' | 'tight' | 'through' | 'none' | 'behind' | 'front' | 'topAndBottom';
export type ImgHorzAlign = 'left' | 'center' | 'right';
export type ImgVertAlign = 'top' | 'center' | 'bottom';
export type ImgHorzRelTo = 'margin' | 'column' | 'page' | 'para';
export type ImgVertRelTo = 'margin' | 'line' | 'page' | 'para';

export interface ImgLayout {
  wrap: ImgWrap;
  horzAlign?: ImgHorzAlign;   // 정렬 기준 (xPt 없을 때)
  vertAlign?: ImgVertAlign;   // 정렬 기준 (yPt 없을 때)
  horzRelTo?: ImgHorzRelTo;   // 가로 기준점
  vertRelTo?: ImgVertRelTo;   // 세로 기준점
  xPt?: number;               // 명시적 가로 오프셋 (pt)
  yPt?: number;               // 명시적 세로 오프셋 (pt)
  distT?: number;             // 텍스트와의 거리 top (pt)
  distB?: number;
  distL?: number;
  distR?: number;
  behindDoc?: boolean;        // 텍스트 뒤에 배치
  zOrder?: number;
}
export type VAlign = 'top' | 'mid' | 'bot';
export type Heading = 1 | 2 | 3 | 4 | 5 | 6;
export type StrokeKind = 'solid' | 'dash' | 'dot' | 'double' | 'none' | 'dashDot' | 'dashDotDot' | 'wave';

export interface TextProps {
  b?: boolean;
  i?: boolean;
  u?: boolean;
  s?: boolean;
  sup?: boolean;
  sub?: boolean;
  font?: string;
  pt?: number;
  color?: string;
  bg?: string;
}export interface ParaProps {
  align?: Align;
  heading?: Heading;
  styleId?: string;              // DOCX pStyle styleId (e.g. "Heading1", "TOC1")
  hwpStyleId?: number;           // HWP native style index (0=바탕글, 1=본문, ...)
  indentPt?: number;             // 문단 왼쪽 전체 들여쓰기 (pt) — OWPML hc:left
  indentRightPt?: number;        // 문단 오른쪽 전체 들여쓰기 (pt) — OWPML hc:right
  firstLineIndentPt?: number;    // 첫 줄 들여쓰기 (pt, 음수=내어쓰기) — OWPML hc:indent
  spaceBefore?: number;
  spaceAfter?: number;
  lineHeight?: number;           // 줄 간격 배율 (예: 1.5 = 150%)
  lineHeightFixed?: number;      // 고정 줄 높이 (pt) — OWPML lineSpacing type="FIXED"
  lineHeightRule?: 'exact' | 'atLeast'; // FIXED/AT_LEAST 의미를 출력까지 보존
  listLv?: number;
  listOrd?: boolean;
  listMark?: string;
  verAlign?: 'baseline' | 'top' | 'center' | 'bottom';
  lineWrap?: 'break' | 'squeeze' | 'keep';
}
export interface Stroke {
  kind: StrokeKind;
  pt: number;
  color: string;
}

export interface CellProps {
  top?: Stroke;
  bot?: Stroke;
  left?: Stroke;
  right?: Stroke;
  bg?: string;
  padPt?: number;      // 모든 방향 균일 패딩 (하위 호환)
  padT?: number;       // 상단 패딩 (pt)
  padB?: number;       // 하단 패딩
  padL?: number;       // 좌측 패딩
  padR?: number;       // 우측 패딩
  align?: Align;
  va?: VAlign;
  isHeader?: boolean;
}

export interface TableLook {
  firstRow?: boolean;
  lastRow?: boolean;
  firstCol?: boolean;
  lastCol?: boolean;
  bandedRows?: boolean;
  bandedCols?: boolean;
}

export interface GridProps {
  widthPct?: number;
  colWidths?: number[];   // column widths in points
  cellPadT?: number;      // table-level default cell padding (pt)
  cellPadB?: number;
  cellPadL?: number;
  cellPadR?: number;
  defaultStroke?: Stroke;
  look?: TableLook;
  headerRow?: boolean;
  align?: Align;          // 표 정렬: 'left' | 'center' | 'right' | 'justify'
  layout?: ImgLayout;     // 표 배치/위치 정보 (없으면 inline 흐름 표)
}

/**
 * 여백 계약 (HWP/HWPX PAGE_DEF·hp:margin 과 1:1 대응)
 * mt / mb        : 위쪽 / 아래쪽 여백 — 머리말·꼬리말을 포함하지 않는다
 * headerPt       : 머리말 여백 (별도 값)
 * footerPt       : 꼬리말 여백 (별도 값)
 * 어떤 인코더도 mt 에 headerPt 를 더해 저장해서는 안 된다.
 * DOCX 로 내보낼 때 w:pgMar 의 top/header 의미가 다르면
 * DocxEncoder 안에서만 변환하고, IR 값은 그대로 둔다.
 */
export interface PageDims {
  wPt: number;
  hPt: number;
  mt: number;
  mb: number;
  ml: number;
  mr: number;
  orient?: 'portrait' | 'landscape';
  headerPt?: number;
  footerPt?: number;
}

export interface DocMeta {
  title?: string;
  author?: string;
  subject?: string;
  desc?: string;
  keywords?: string;
  created?: string;
  modified?: string;
  zoom?: number;
  viewMode?: string;
}

